package com.adent.finance.api;
import com.adent.patient.repository.PatientRepository; import com.adent.shared.exception.NotFoundException; import com.adent.shared.security.CurrentUser; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/finance") public class FinanceController { private final CurrentUser current;private final JdbcTemplate jdbc;private final PatientRepository patients;public FinanceController(CurrentUser c,JdbcTemplate j,PatientRepository p){current=c;jdbc=j;patients=p;} @GetMapping("/services") @PreAuthorize("hasAnyRole('OWNER','ADMIN','RECEPTION','DENTIST')") public List<Map<String,Object>> services(){return jdbc.queryForList("select id,code,name,reference_price,min_price,max_price,active from service_catalog where tenant_id=? order by name",current.tenantId());} @PostMapping("/services") @PreAuthorize("hasRole('ADMIN')") public Map<String,Object> addService(@RequestBody ServiceRequest r){UUID id=UUID.randomUUID();jdbc.update("insert into service_catalog(id,tenant_id,code,name,reference_price,min_price,max_price,active) values(?,?,?,?,?,?,?,true)",id,current.tenantId(),r.code(),r.name(),r.referencePrice(),r.minPrice(),r.maxPrice());return Map.of("id",id,"name",r.name(),"referencePrice",r.referencePrice());} @GetMapping("/payments/patient/{patientId}") @PreAuthorize("hasAnyRole('OWNER','ADMIN','RECEPTION')") public List<Map<String,Object>> payments(@PathVariable UUID patientId){return jdbc.queryForList("select id,amount,payment_method,paid_at,notes from payments where tenant_id=? and patient_id=? order by paid_at desc",current.tenantId(),patientId);} @PostMapping("/payments") @PreAuthorize("hasAnyRole('OWNER','ADMIN','RECEPTION')") public Map<String,Object> pay(@RequestBody PaymentRequest r){patients.findByIdAndTenantId(r.patientId(),current.tenantId()).orElseThrow(()->new NotFoundException("Paciente no encontrado"));UUID id=UUID.randomUUID();OffsetDateTime now=OffsetDateTime.now();jdbc.update("insert into payments(id,tenant_id,patient_id,encounter_id,amount,payment_method,paid_at,notes) values(?,?,?,?,?,?,?,?)",id,current.tenantId(),r.patientId(),r.encounterId(),r.amount(),r.paymentMethod(),now,r.notes());return Map.of("id",id,"amount",r.amount(),"paidAt",now.toString());} public record ServiceRequest(String code,String name,BigDecimal referencePrice,BigDecimal minPrice,BigDecimal maxPrice){} public record PaymentRequest(UUID patientId,UUID encounterId,BigDecimal amount,String paymentMethod,String notes){} }
